// BEFORE: a class with several reasons to change (violates SRP).
class OrderReport {
    void generate() { /* report logic */ }
    void saveToFile() { /* persistence logic */ }   // a DIFFERENT reason to change
    void email() { /* notification logic */ }        // another reason
}
//   One change to file format, email config, or report logic edits this class.

// AFTER: SRP — each class has ONE responsibility.
class OrderReport { void generate() {} }            // report logic only
class OrderReportFileRepository { void save(OrderReport r) {} }  // persistence
class OrderReportMailer { void mail(OrderReport r) {} }          // notification

// OCP + DIP: adding a new notification (SMS) shouldn't edit existing classes.
interface Notifier { void send(OrderReport r); }
class EmailNotifier implements Notifier { public void send(OrderReport r) {} }
class SmsNotifier   implements Notifier { public void send(OrderReport r) {} }  // new
//   The report service depends on `Notifier` (the abstraction), so adding SMS
//   changes NO existing code -> Open/Closed + Dependency Inversion together.

// DRY: a tax-rate formula used in three places lives in ONE method.
// KISS/YAGNI: don't add a 'future tax-strategy plugin' until a second
//   tax rule actually exists -> build for now, not for imaginary later.

