// VIOLATION SIGNALS: Multiple unrelated imports
import javax.mail.*;
import java.sql.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.web.bind.annotation.*;

@RestController // Smell: Multiple stereotypes in one class
class OrderProcessor {
    private DataSource dataSource;        // Database concern
    private JavaMailSender mailSender;    // Email concern
    private ObjectMapper jsonMapper;      // Serialization concern
    private PaymentGateway paymentGateway; // External API concern

    @PostMapping("/orders") // Responsibility 1: HTTP handling
    public String createOrder(@RequestBody String json) throws Exception {
        Order order = jsonMapper.readValue(json, Order.class); // Responsibility 2: Parsing

        if (order.total() < 0) return "Invalid"; // Responsibility 3: Validation

        Connection conn = dataSource.getConnection(); // Responsibility 4: DB access
        conn.prepareStatement("INSERT INTO orders...").executeUpdate();

        paymentGateway.charge(order.total()); // Responsibility 5: External API

        MimeMessage msg = mailSender.createMimeMessage(); // Responsibility 6: Email
        msg.setSubject("Order confirmed");
        mailSender.send(msg);

        return "Success"; // Six reasons to change!
    }
}

