The layers demonstrate separation of concerns. SRP is evaluated separately inside each class or module by asking which actor or policy makes it change.

// COMPLIANT: 8 methods, 1 responsibility (data access)
@Repository
class OrderRepository {
    private final JdbcTemplate jdbc;

    public void save(Order order) {
        jdbc.update("INSERT INTO orders...", order.id(), order.total());
    }

    public Optional<Order> findById(Long id) {
        return jdbc.query("SELECT * FROM orders WHERE id=?", 
            rs -> rs.next() ? Optional.of(mapRow(rs)) : Optional.empty(), id);
    }

    public List<Order> findByCustomerId(Long customerId) {
        return jdbc.query("SELECT * FROM orders WHERE customer_id=?",
            this::mapRow, customerId);
    }

    public void update(Order order) {
        jdbc.update("UPDATE orders SET total=? WHERE id=?", order.total(), order.id());
    }

    public void delete(Long id) {
        jdbc.update("DELETE FROM orders WHERE id=?", id);
    }

    public boolean exists(Long id) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM orders WHERE id=?", 
            Integer.class, id) > 0;
    }

    public long count() {
        return jdbc.queryForObject("SELECT COUNT(*) FROM orders", Long.class);
    }

    private Order mapRow(ResultSet rs) throws SQLException {
        return new Order(rs.getLong("id"), rs.getBigDecimal("total"));
    }
    // Eight methods, all serving one responsibility: Order data access
}
